  function px(t) {
    return (Math.sin(P.fx * t + P.px) * Math.exp(-P.dx * t) +
            P.sx * Math.sin(P.gx * t + P.qx) * Math.exp(-P.ex * t)) / (1 + P.sx);
  }
  function py(t) {
    return (Math.sin(P.fy * t + P.py) * Math.exp(-P.dy * t) +
            P.sy * Math.sin(P.gy * t + P.qy) * Math.exp(-P.ey * t)) / (1 + P.sy);
  }

