    var time = "";
    try {
      time = new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
    } catch (e) {
      time = "";
    }
    var pct = (Math.abs(P.det) * 100).toFixed(2);
    var way = P.det > 0 ? "sharp" : "flat";
