  body {
    font-family: Georgia, "Times New Roman", serif;
    font-size: 19px;
    line-height: 1.7;
    min-height: 100vh;
  }
  main {
    max-width: 680px;
    margin: 0 auto;
    padding: 72px 24px 48px;
  }
  h1 {
    font-weight: normal;
    font-size: 2.1em;
