    list-style: none;
    padding: 0;
    margin: 0;
  }
  ul.notes li {
    padding: 0.55em 0;
    border-bottom: 1px dotted var(--line);
    color: var(--ink);
  }
  ul.notes li:last-child { border-bottom: none; }
