    transition: opacity 0.2s, background 0.2s;
  }
  button:hover, button:focus-visible {
    opacity: 1;
    background: rgba(159, 184, 212, 0.1);
    outline: none;
  }
  footer {
    position: fixed;
    bottom: 1rem;
