  </div>
  <footer>
    <div>A quiet place</div>
    <div id="clock">— : —</div>
  </footer>
</div>

<script>
const canvas = document.getElementById('sky');
const ctx = canvas.getContext('2d');
let W, H;
function resize() {
  W = canvas.width = window.innerWidth * devicePixelRatio;
  H = canvas.height = window.innerHeight * devicePixelRatio;
}
resize();
window.addEventListener('resize', resize);

let mouse = { x: W/2, y: H/2, active: false };
window.addEventListener('mousemove', e => {
  mouse.x = e.clientX * devicePixelRatio;
  mouse.y = e.clientY * devicePixelRatio;
  mouse.active = true;
});
window.addEventListener('mouseleave', () => mouse.active = false);
window.addEventListener('touchmove', e => {
  if (e.touches[0]) {
    mouse.x = e.touches[0].clientX * devicePixelRatio;
    mouse.y = e.touches[0].clientY * devicePixelRatio;
    mouse.active = true;
  }
});

const particles = [];
const N = 140;
for (let i = 0; i < N; i++) {
  particles.push({
    x: Math.random() * W,
    y: Math.random() * H,
    vx: (Math.random() - 0.5) * 0.3,
    vy: (Math.random() - 0.5) * 0.3,
    r: Math.random() * 2 + 0.5,
    hue: 200 + Math.random() * 60
  });
}

let t = 0;
function frame() {
  t += 0.003;
  // atmospheric gradient
  const g = ctx.createRadialGradient(W*0.3, H*0.2, 0, W*0.5, H*0.5, Math.max(W,H));
  const shift = Math.sin(t) * 10;
  g.addColorStop(0, `hsl(${230 + shift}, 35%, 10%)`);
  g.addColorStop(0.5, `hsl(${250 + shift}, 30%, 6%)`);
  g.addColorStop(1, `hsl(${210}, 40%, 3%)`);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  // drifting particles
  for (const p of particles) {
    // gentle wind
    p.vx += Math.sin(t + p.y * 0.001) * 0.002;
    p.vy += Math.cos(t + p.x * 0.001) * 0.002;

    // mouse influence
    if (mouse.active) {
      const dx = p.x - mouse.x;
      const dy = p.y - mouse.y;
      const d2 = dx*dx + dy*dy;
      const R = 180 * devicePixelRatio;
      if (d2 < R*R && d2 > 0) {
        const d = Math.sqrt(d2);
        const f = (1 - d / R) * 0.4;
        p.vx += (dx / d) * f;
        p.vy += (dy / d) * f;
      }
    }

    // damping
    p.vx *= 0.98;
    p.vy *= 0.98;
    p.x += p.vx;
    p.y += p.vy;

    // wrap
    if (p.x < 0) p.x += W;
    if (p.x > W) p.x -= W;
    if (p.y < 0) p.y += H;
    if (p.y > H) p.y -= H;

    const glow = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, p.r * 8);
    glow.addColorStop(0, `hsla(${p.hue}, 70%, 80%, 0.5)`);
    glow.addColorStop(1, `hsla(${p.hue}, 70%, 80%, 0)`);
    ctx.fillStyle = glow;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.r * 8, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = `hsla(${p.hue}, 80%, 90%, 0.9)`;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
    ctx.fill();
  }

  requestAnimationFrame(frame);
}
frame();

// clock
function updateClock() {
  const d = new Date();
  const h = String(d.getHours()).padStart(2,'0');
  const m = String(d.getMinutes()).padStart(2,'0');
  document.getElementById('clock').textContent = `${h} : ${m}`;
}
updateClock();
setInterval(updateClock, 10000);

// weather states
const states = ['clear · drifting','thin cloud · low wind','bright · still','soft haze','evening blue','a little weather'];
let si = 0;
setInterval(() => {
  si = (si + 1) % states.length;
  document.getElementById('weather').textContent = states[si];
}, 7000);

// title hover
const spans = document.querySelectorAll('#title span');
spans.forEach((s, i) => {
  s.addEventListener('mouseenter', () => {
    s.style.transform = `translateY(${(Math.random()-0.5)*8}px) rotate(${(Math.random()-0.5)*4}deg)`;
    s.style.color = `hsl(${200 + Math.random()*80}, 60%, 85%)`;
  });
  s.addEventListener('mouseleave', () => {
    s.style.transform = '';
    s.style.color = '';
  });
});
</script>
</body>
</html>
