}

gal.addEventListener("click", ev=>{
  const b = ev.target.closest(".labelbtn");
  if(!b) return;
  const art = b.closest(".exhibit");
  const open = art.classList.toggle("open");
  b.setAttribute("aria-expanded", open ? "true" : "false");
  b.textContent = open ? "Close the label" : "Read the label";
  if(open){ read++; readEl.textContent = read; }
});

document.getElementById("rotate").addEventListener("click", render);
render();
</script>
</body>
</html>
