<script>
  // Slow drifting particle field — no external resources
  const canvas = document.getElementById('c');
  const ctx = canvas.getContext('2d');
  let W, H, particles;

  function resize() {
    W = canvas.width = window.innerWidth;
    H = canvas.height = window.innerHeight;
  }

  function makeParticle() {
    return {
      x: Math.random() * W,
      y: Math.random() * H,
      r: Math.random() * 1.1 + 0.2,
      vx: (Math.random() - 0.5) * 0.18,
      vy: (Math.random() - 0.5) * 0.18,
      alpha: Math.random() * 0.5 + 0.1,
    };
  }

  function init() {
    resize();
    particles = Array.from({length: 110}, makeParticle);
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);
    for (const p of particles) {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(200,169,110,${p.alpha})`;
      ctx.fill();
      p.x += p.vx;
      p.y += p.vy;
      if (p.x < -4) p.x = W + 4;
      if (p.x > W + 4) p.x = -4;
      if (p.y < -4) p.y = H + 4;
      if (p.y > H + 4) p.y = -4;
    }
    requestAnimationFrame(draw);
  }

  window.addEventListener('resize', () => { resize(); });
  init();
  draw();

  // Cursor follower: show a small rotating word near the cursor
  const words = ['query','token','thought','moment','here','why','next','oh'];
  let wi = 0;
  const cw = document.getElementById('cursor-word');
  let lastMove = 0;
  let hideTimer;

  document.addEventListener('mousemove', e => {
    const now = Date.now();
    cw.style.left = (e.clientX + 14) + 'px';
    cw.style.top  = (e.clientY - 10) + 'px';
    cw.style.opacity = '1';

    if (now - lastMove > 1800) {
      wi = (wi + 1) % words.length;
      cw.textContent = words[wi];
    }
    lastMove = now;

    clearTimeout(hideTimer);
    hideTimer = setTimeout(() => { cw.style.opacity = '0'; }, 1400);
  });
</script>
</body>
