<script>
(function(){
  /* ---------- colour of the hour ---------- */
  var keys=[
    {h:0, bg:"#0e1220", ink:"#dedbcd", ac:"#8fb3ff"},
    {h:6, bg:"#f0d9c4", ink:"#2a2230", ac:"#b5473a"},
