(function () {
  // greeting by local time
  var h = new Date().getHours();
  var g = h < 5 ? "Hello, small hours" : h < 12 ? "Good morning" : h < 18 ? "Good afternoon" : h < 22 ? "Good evening" : "Late, and welcome";
