    {h:22.0,  top:"#070b18", mid:"#0c1226", bot:"#161f36", star:0.90},
    {h:24.0,  top:"#05070f", mid:"#0a1020", bot:"#121a2e", star:1.00}
  ];

  function hexToRgb(hex){
    var h = hex.replace("#","");
    return [
      parseInt(h.slice(0,2),16),
      parseInt(h.slice(2,4),16),
      parseInt(h.slice(4,6),16)
    ];
