    var a = KF[i], b = KF[i+1];
    var span = (b.h - a.h) || 1;
    var t = (h - a.h) / span;
    t = t < 0 ? 0 : (t > 1 ? 1 : t);
    return {
      top: mix(a.top, b.top, t),
      mid: mix(a.mid, b.mid, t),
      bot: mix(a.bot, b.bot, t),
      midRaw: [
        lerp(a.mid[0], b.mid[0], t),
        lerp(a.mid[1], b.mid[1], t),
        lerp(a.mid[2], b.mid[2], t)
      ],
      star: lerp(a.star, b.star, t)
    };
