    }

    var g = greeting(h);
    if (g !== lastGreeting) {
      headingEl.textContent = g;
      lastGreeting = g;
    }

    var hh = Math.floor(h) % 24;
    var mm = Math.floor((h % 1) * 60);
    var c = pad(hh) + ":" + pad(mm);
    if (c !== lastClock) {
      clockEl.textContent = c;
      lastClock = c;
    }
  }

