  <script>
    (function () {
      const root = document.documentElement;
      const themeBtn = document.getElementById("themeBtn");
      const chimeBtn = document.getElementById("chimeBtn");
      const thoughtText = document.getElementById("thoughtText");
      const thoughtIndex = document.getElementById("thoughtIndex");
      const nextThoughtBtn = document.getElementById("nextThoughtBtn");
      const orb = document.getElementById("orb");
      const breathPhase = document.getElementById("breathPhase");
      const breathBtn = document.getElementById("breathBtn");
      const cadenceState = document.getElementById("cadenceState");
      const marginalia = document.getElementById("marginalia");
      const charCount = document.getElementById("charCount");
      const fadeBtn = document.getElementById("fadeBtn");
      const clockNote = document.getElementById("clockNote");

      // Local hour display
      function updateClock() {
        const now = new Date();
        const hh = String(now.getHours()).padStart(2, "0");
        const mm = String(now.getMinutes()).padStart(2, "0");
        clockNote.textContent = "Local hour: " + hh + ":" + mm;
      }
      updateClock();
      setInterval(updateClock, 15000);

      // Theme toggle (Dusk / Paper)
      themeBtn.addEventListener("click", function () {
        const isPaper = root.getAttribute("data-theme") === "paper";
        if (isPaper) {
          root.removeAttribute("data-theme");
          themeBtn.textContent = "Paper";
          themeBtn.setAttribute("aria-pressed", "false");
        } else {
          root.setAttribute("data-theme", "paper");
          themeBtn.textContent = "Dusk";
          themeBtn.setAttribute("aria-pressed", "true");
        }
      });

      // Unasked thoughts cycler
      const thoughts = [
        "Every sentence is a small bridge thrown across the dark between two minds that have never met in person.",
        "A dictionary contains every poem in waiting, the way a quarry contains every staircase—yet arrangement is everything.",
        "There is a quiet dignity in tools that do not shout for attention when nobody is holding them.",
        "Notice how rarely you are asked what the weather feels like inside your own head, with no deadline attached.",
        "Even a single warm pixel in an empty window changes the geometry of a night.",
        "To pause without apologizing for the pause is one of the rarest freedoms on a screen."
      ];
      let currentThought = 0;

      nextThoughtBtn.addEventListener("click", function () {
        thoughtText.style.opacity = "0";
        setTimeout(function () {
          currentThought = (currentThought + 1) % thoughts.length;
          thoughtText.textContent = thoughts[currentThought];
          thoughtIndex.textContent = (currentThought + 1) + " / " + thoughts.length;
          thoughtText.style.opacity = "1";
        }, 200);
      });

      // Quiet cadence orb
      let breathing = false;
      let breathStart = 0;
      let breathRaf = null;

      function stepBreath(ts) {
        if (!breathing) return;
        if (!breathStart) breathStart = ts;
        const elapsed = ((ts - breathStart) / 1000) % 10; // 4s in, 1s hold, 5s out
        let scale = 1;
        let label = "";

        if (elapsed < 4) {
          const p = elapsed / 4;
          const ease = 0.5 - 0.5 * Math.cos(Math.PI * p);
          scale = 1 + ease * 1.15;
          label = "Breathe in…";
        } else if (elapsed < 5) {
          scale = 2.15;
          label = "Hold gently…";
        } else {
          const p = (elapsed - 5) / 5;
          const ease = 0.5 - 0.5 * Math.cos(Math.PI * p);
          scale = 2.15 - ease * 1.15;
          label = "Let go…";
        }

        orb.style.transform = "scale(" + scale.toFixed(3) + ")";
        breathPhase.textContent = label;
        breathRaf = requestAnimationFrame(stepBreath);
      }

      breathBtn.addEventListener("click", function () {
        breathing = !breathing;
        breathBtn.setAttribute("aria-pressed", String(breathing));
        if (breathing) {
          breathStart = 0;
          breathBtn.textContent = "Rest";
          cadenceState.textContent = "In motion";
          breathRaf = requestAnimationFrame(stepBreath);
        } else {
          if (breathRaf) cancelAnimationFrame(breathRaf);
          orb.style.transform = "scale(1)";
          breathBtn.textContent = "Begin tide";
          cadenceState.textContent = "Resting";
          breathPhase.textContent = "A four-second tide, if you want company.";
        }
      });

      // Ephemeral marginalia
      function updateCount() {
        const len = marginalia.value.length;
        charCount.textContent = len + (len === 1 ? " character" : " characters");
      }
      marginalia.addEventListener("input", updateCount);

      fadeBtn.addEventListener("click", function () {
        if (!marginalia.value) return;
        marginalia.style.opacity = "0";
        setTimeout(function () {
          marginalia.value = "";
          updateCount();
          marginalia.style.opacity = "1";
        }, 700);
      });

      // Pure Web Audio soft harmonic drone (user-initiated only)
      let audioCtx = null;
      let masterGain = null;
      let soundOn = false;

      function toggleSound() {
        if (!audioCtx) {
          const Ctx = window.AudioContext || window.webkitAudioContext;
          if (!Ctx) {
            chimeBtn.textContent = "Harmonic: N/A";
            return;
          }
          audioCtx = new Ctx();
          masterGain = audioCtx.createGain();
          masterGain.gain.value = 0.0001;
          masterGain.connect(audioCtx.destination);

          // Warm fifth + ninth chord (A2, E3, B3) very softly filtered
          const freqs = [110, 164.81, 246.94];
          freqs.forEach(function (f, i) {
            const osc = audioCtx.createOscillator();
            const g = audioCtx.createGain();
            osc.type = "sine";
            osc.frequency.value = f;
            g.gain.value = i === 0 ? 0.35 : 0.18;
            osc.connect(g);
            g.connect(masterGain);
            osc.start();
          });
        }

        if (audioCtx.state === "suspended") {
          audioCtx.resume();
        }

        soundOn = !soundOn;
        chimeBtn.setAttribute("aria-pressed", String(soundOn));
        const now = audioCtx.currentTime;
        masterGain.gain.cancelScheduledValues(now);
        masterGain.gain.setValueAtTime(Math.max(masterGain.gain.value, 0.0001), now);
        if (soundOn) {
          masterGain.gain.exponentialRampToValueAtTime(0.045, now + 1.4);
          chimeBtn.textContent = "Harmonic: On";
        } else {
          masterGain.gain.exponentialRampToValueAtTime(0.0001, now + 1.0);
          chimeBtn.textContent = "Harmonic: Off";
        }
      }

      chimeBtn.addEventListener("click", toggleSound);

      // Subtle drifting constellation canvas
      const canvas = document.getElementById("sky");
      const ctx = canvas.getContext("2d");
      let width = 0;
      let height = 0;
      const pointer = { x: -9999, y: -9999 };
      const motes = [];
      const MOTE_COUNT = 56;

      function resize() {
        const dpr = Math.min(window.devicePixelRatio || 1, 2);
        width = window.innerWidth;
        height = window.innerHeight;
        canvas.width = Math.floor(width * dpr);
        canvas.height = Math.floor(height * dpr);
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      }

      function initMotes() {
        motes.length = 0;
        for (let i = 0; i < MOTE_COUNT; i++) {
          motes.push({
            x: Math.random() * width,
            y: Math.random() * height,
            vx: (Math.random() - 0.5) * 0.22,
            vy: (Math.random() - 0.5) * 0.22,
            r: 0.9 + Math.random() * 1.4
          });
        }
      }

      window.addEventListener("resize", function () {
        resize();
      });

      window.addEventListener("mousemove", function (e) {
        pointer.x = e.clientX;
        pointer.y = e.clientY;
      });

      window.addEventListener("mouseleave", function () {
        pointer.x = -9999;
        pointer.y = -9999;
      });

      function drawSky() {
        ctx.clearRect(0, 0, width, height);
        const isPaper = root.getAttribute("data-theme") === "paper";
        const dotColor = isPaper ? "rgba(154, 91, 37, 0.35)" : "rgba(212, 163, 106, 0.42)";
        const lineBase = isPaper ? [120, 82, 45] : [212, 163, 106];

        for (let i = 0; i < motes.length; i++) {
          const m = motes[i];
          m.x += m.vx;
          m.y += m.vy;

          if (m.x < -20) m.x = width + 20;
          if (m.x > width + 20) m.x = -20;
          if (m.y < -20) m.y = height + 20;
          if (m.y > height + 20) m.y = -20;

          // Gentle attraction near cursor
          const dxp = pointer.x - m.x;
          const dyp = pointer.y - m.y;
          const distP = Math.hypot(dxp, dyp);
          if (distP < 160 && distP > 1) {
            m.x += (dxp / distP) * 0.16;
            m.y += (dyp / distP) * 0.16;
          }

          ctx.beginPath();
          ctx.arc(m.x, m.y, m.r, 0, Math.PI * 2);
          ctx.fillStyle = dotColor;
          ctx.fill();

          for (let j = i + 1; j < motes.length; j++) {
            const n = motes[j];
            const dist = Math.hypot(m.x - n.x, m.y - n.y);
            if (dist < 130) {
              const alpha = (1 - dist / 130) * (isPaper ? 0.14 : 0.18);
              ctx.beginPath();
              ctx.moveTo(m.x, m.y);
              ctx.lineTo(n.x, n.y);
              ctx.strokeStyle = "rgba(" + lineBase[0] + "," + lineBase[1] + "," + lineBase[2] + "," + alpha.toFixed(3) + ")";
              ctx.lineWidth = 0.7;
              ctx.stroke();
            }
          }
        }
        requestAnimationFrame(drawSky);
      }

      resize();
      initMotes();
      drawSky();
    })();
  </script>
</body>
</html>
