    const dotColor = getVar("--canvas-dot");
    const linkColor = getVar("--canvas-link");

    for (let i = 0; i < points.length; i++) {
      const p = points[i];
      if (!paused) {
        p.x += p.vx;
        p.y += p.vy;

        if (p.x < 0 || p.x > width) p.vx *= -1;
        if (p.y < 0 || p.y > height) p.vy *= -1;

        p.x = Math.max(0, Math.min(width, p.x));
        p.y = Math.max(0, Math.min(height, p.y));

        if (pointer.active) {
          const dx = pointer.x - p.x;
          const dy = pointer.y - p.y;
          const dist = Math.hypot(dx, dy);
          if (dist > 18 && dist < 140) {
            p.vx += (dx / dist) * 0.008;
            p.vy += (dy / dist) * 0.008;
          }
        }

        const speed = Math.hypot(p.vx, p.vy);
        if (speed > 0.75) {
          p.vx = (p.vx / speed) * 0.75;
          p.vy = (p.vy / speed) * 0.75;
        }
      }
    }

    ctx.lineWidth = 1;
    for (let i = 0; i < points.length; i++) {
      for (let j = i + 1; j < points.length; j++) {
        const dx = points[i].x - points[j].x;
        const dy = points[i].y - points[j].y;
        const dist = Math.hypot(dx, dy);
        if (dist < 105) {
          ctx.strokeStyle = linkColor;
          ctx.globalAlpha = 1 - dist / 105;
          ctx.beginPath();
          ctx.moveTo(points[i].x, points[i].y);
          ctx.lineTo(points[j].x, points[j].y);
          ctx.stroke();
        }
      }

      if (pointer.active) {
        const dx = points[i].x - pointer.x;
        const dy = points[i].y - pointer.y;
        const dist = Math.hypot(dx, dy);
        if (dist < 130) {
          ctx.strokeStyle = linkColor;
          ctx.globalAlpha = (1 - dist / 130) * 0.9;
          ctx.beginPath();
          ctx.moveTo(points[i].x, points[i].y);
          ctx.lineTo(pointer.x, pointer.y);
          ctx.stroke();
        }
      }
    }

    ctx.globalAlpha = 1;
    ctx.fillStyle = dotColor;
    for (let i = 0; i < points.length; i++) {
      const p = points[i];
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
      ctx.fill();
    }

    requestAnimationFrame(tick);
  }

  canvas.addEventListener("mousemove", function (e) {
    const rect = canvas.getBoundingClientRect();
    pointer.x = e.clientX - rect.left;
    pointer.y = e.clientY - rect.top;
    pointer.active = true;
  });

  canvas.addEventListener("mouseleave", function () {
    pointer.active = false;
  });

  canvas.addEventListener("click", function (e) {
    const rect = canvas.getBoundingClientRect();
    const cx = e.clientX - rect.left;
    const cy = e.clientY - rect.top;
    points.forEach(function (p) {
      const dx = p.x - cx;
      const dy = p.y - cy;
      const dist = Math.hypot(dx, dy) || 1;
      if (dist < 140) {
        p.vx += (dx / dist) * 0.65;
        p.vy += (dy / dist) * 0.65;
      }
    });
  });

  pauseBtn.addEventListener("click", function () {
    paused = !paused;
    pauseBtn.textContent = paused ? "Resume" : "Pause";
    statusEl.textContent = paused ? count + " points resting" : count + " points drifting";
  });

  scatterBtn.addEventListener("click", function () {
    points.forEach(function (p) {
      p.vx = (Math.random() - 0.5) * 1.1;
      p.vy = (Math.random() - 0.5) * 1.1;
    });
  });

  window.addEventListener("resize", resize);
  resize();
  initPoints();
  tick();

  // Local clock
  function updateClock() {
    const now = new Date();
    const h = String(now.getHours()).padStart(2, "0");
    const m = String(now.getMinutes()).padStart(2, "0");
    document.getElementById("clockNote").textContent = "Local hour: " + h + ":" + m;
  }
  updateClock();
  setInterval(updateClock, 15000);
})();
</script>
</body>
</html>
