        const half = size * 0.5;
        const radius = size * 0.415;
        inkCtx.save();
        inkCtx.strokeStyle = cssVar("--guide");
        inkCtx.lineWidth = 0.75;

        inkCtx.beginPath();
        inkCtx.arc(half, half, radius, 0, Math.PI * 2);
        inkCtx.stroke();

        inkCtx.beginPath();
        inkCtx.moveTo(half - 8, half);
        inkCtx.lineTo(half + 8, half);
        inkCtx.moveTo(half, half - 8);
        inkCtx.lineTo(half, half + 8);
        inkCtx.stroke();
        inkCtx.restore();
      }

      function resizeCanvas() {
        const rect = plate.getBoundingClientRect();
        size = Math.max(200, Math.floor(rect.width));
        dpr = Math.min(window.devicePixelRatio || 1, 2);

        [inkCanvas, nibCanvas].forEach((c) => {
          c.width = Math.floor(size * dpr);
          c.height = Math.floor(size * dpr);
        });

        inkCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
        nibCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
        replayAllPoints();
      }

      function replayAllPoints() {
        inkCtx.clearRect(0, 0, size, size);
        drawGuides();

        if (points.length < 2) return;
        inkCtx.save();
        inkCtx.strokeStyle = cssVar("--trace");
        inkCtx.lineWidth = 0.7;
        inkCtx.lineCap = "round";
        inkCtx.lineJoin = "round";

        // Draw in modest chunks to preserve delicate overlapping alpha density
        const CHUNK = 160;
        for (let i = 1; i < points.length; i += CHUNK) {
          const end = Math.min(points.length, i + CHUNK);
          inkCtx.beginPath();
          const start = toCanvas(points[i - 1]);
          inkCtx.moveTo(start.cx, start.cy);
          for (let j = i; j < end; j++) {
            const p = toCanvas(points[j]);
            inkCtx.lineTo(p.cx, p.cy);
          }
          inkCtx.stroke();
        }
        inkCtx.restore();

        drawNib(points[points.length - 1]);
      }

      function drawNib(pt) {
        nibCtx.clearRect(0, 0, size, size);
        if (!pt || resting) return;
        const { cx, cy } = toCanvas(pt);
        const color = cssVar("--trace-nib");

        nibCtx.save();
        nibCtx.fillStyle = color;
        nibCtx.globalAlpha = Math.max(0.25, Math.min(0.95, pt.env * 1.4));
        nibCtx.beginPath();
        nibCtx.arc(cx, cy, 2.2, 0, Math.PI * 2);
        nibCtx.fill();

        nibCtx.strokeStyle = color;
        nibCtx.lineWidth = 0.75;
        nibCtx.globalAlpha = 0.35;
        nibCtx.beginPath();
        nibCtx.arc(cx, cy, 6.5, 0, Math.PI * 2);
        nibCtx.stroke();
        nibCtx.restore();
      }

      function updateStatus() {
        const r = RATIOS[ratioIndex];
        readout.textContent = `${r.name} · ${r.label} · drift ${drift.toFixed(3)}`;

        let label = "tracing";
        if (resting) label = "at rest";
        else if (paused) label = "paused";

        statusText.innerHTML = `<span class="status-dot${resting || paused ? " rest" : ""}"></span>${label}`;
        pauseBtn.textContent = paused ? "resume" : "pause";
        pauseBtn.setAttribute("aria-pressed", String(paused));
      }

      function resetTrace(useRandomPhases = true) {
        if (useRandomPhases) phases = randomPhases();
        t = 0;
        resting = false;
        paused = false;
        points = [samplePoint(0)];
        inkCtx.clearRect(0, 0, size, size);
        nibCtx.clearRect(0, 0, size, size);
        drawGuides();
        updateStatus();
      }

      function tick() {
        if (!paused && !resting) {
          inkCtx.save();
          inkCtx.strokeStyle = cssVar("--trace");
          inkCtx.lineWidth = 0.7;
          inkCtx.lineCap = "round";
          inkCtx.lineJoin = "round";
          inkCtx.beginPath();

          let prev = points[points.length - 1];
          let pCanvas = toCanvas(prev);
          inkCtx.moveTo(pCanvas.cx, pCanvas.cy);

          for (let s = 0; s < STEPS_PER_FRAME; s++) {
            t += DT;
            const next = samplePoint(t);
            points.push(next);
            const nc = toCanvas(next);
            inkCtx.lineTo(nc.cx, nc.cy);
            prev = next;

            if (next.env < 0.032 || points.length >= MAX_POINTS) {
              resting = true;
              break;
            }
          }

          inkCtx.stroke();
          inkCtx.restore();
          drawNib(prev);
          if (resting) updateStatus();
        }
        requestAnimationFrame(tick);
      }

      // Gentle offline Web Audio harmonic drone (muted unless invited)
      let audioCtx = null;
      let soundOn = false;
      let masterGain = null;
      let oscA = null;
      let oscB = null;
      let lfo = null;
      const BASE_FREQ = 220; // A3

      function startSound() {
        if (!audioCtx) {
          const AudioCtor = window.AudioContext || window.webkitAudioContext;
          if (!AudioCtor) return;
          audioCtx = new AudioCtor();

          masterGain = audioCtx.createGain();
          masterGain.gain.value = 0.0001;

          const filter = audioCtx.createBiquadFilter();
          filter.type = "lowpass";
          filter.frequency.value = 920;

          // Subtle breathing LFO
          lfo = audioCtx.createOscillator();
          const lfoGain = audioCtx.createGain();
          lfo.frequency.value = 0.16;
          lfoGain.gain.value = 0.012;

          oscA = audioCtx.createOscillator();
          oscB = audioCtx.createOscillator();
          oscA.type = "sine";
          oscB.type = "sine";

          const gA = audioCtx.createGain();
          const gB = audioCtx.createGain();
          gA.gain.value = 0.55;
          gB.gain.value = 0.45;

          oscA.connect(gA).connect(filter);
          oscB.connect(gB).connect(filter);
          filter.connect(masterGain).connect(audioCtx.destination);
          lfo.connect(lfoGain).connect(masterGain.gain);

          oscA.start();
          oscB.start();
          lfo.start();
        }

        if (audioCtx.state === "suspended") audioCtx.resume();
        tuneSound();
        const now = audioCtx.currentTime;
        masterGain.gain.cancelScheduledValues(now);
        masterGain.gain.setValueAtTime(Math.max(0.0001, masterGain.gain.value), now);
        masterGain.gain.linearRampToValueAtTime(0.065, now + 0.85);
        soundOn = true;
        soundBtn.setAttribute("aria-pressed", "true");
        soundBtn.textContent = "quiet";
      }

      function stopSound() {
        if (!audioCtx || !masterGain) return;
        const now = audioCtx.currentTime;
        masterGain.gain.cancelScheduledValues(now);
        masterGain.gain.setValueAtTime(masterGain.gain.value, now);
        masterGain.gain.linearRampToValueAtTime(0.0001, now + 0.55);
        soundOn = false;
        soundBtn.setAttribute("aria-pressed", "false");
        soundBtn.textContent = "listen";
      }

      function tuneSound() {
        if (!audioCtx || !oscA || !oscB) return;
        const r = RATIOS[ratioIndex].value;
        const now = audioCtx.currentTime;
        oscA.frequency.setTargetAtTime(BASE_FREQ, now, 0.12);
        // Subtle detuning mirrors the visual drift
        oscB.frequency.setTargetAtTime(BASE_FREQ * r + drift * 22, now, 0.12);
      }

      // Build ratio controls
      RATIOS.forEach((r, idx) => {
        const btn = document.createElement("button");
        btn.type = "button";
        btn.className = "ratio-btn" + (idx === ratioIndex ? " active" : "");
        btn.textContent = `${r.name} · ${r.label}`;
        btn.addEventListener("click", () => {
          ratioIndex = idx;
          ratioGroup.querySelectorAll(".ratio-btn").forEach((b, i) => {
            b.classList.toggle("active", i === idx);
          });
          resetTrace(true);
          if (soundOn) tuneSound();
        });
        ratioGroup.appendChild(btn);
      });

      // Marginalia
      let noteIndex = 0;
      function showNote(idx) {
        noteIndex = (idx + NOTES.length) % NOTES.length;
        const n = NOTES[noteIndex];
        noteBody.style.opacity = "0";
        window.setTimeout(() => {
          noteBody.innerHTML = `<span class="note-title">${n.title}</span>${n.text}`;
          noteBody.style.opacity = "1";
        }, 140);
        romanNav.querySelectorAll(".roman-btn").forEach((b, i) => {
          b.classList.toggle("active", i === noteIndex);
        });
      }

      NOTES.forEach((n, idx) => {
        const btn = document.createElement("button");
        btn.type = "button";
        btn.className = "roman-btn" + (idx === 0 ? " active" : "");
        btn.textContent = n.roman;
        btn.setAttribute("aria-label", `Note ${n.roman}`);
        btn.addEventListener("click", () => showNote(idx));
        romanNav.appendChild(btn);
      });
      noteBody.innerHTML = `<span class="note-title">${NOTES[0].title}</span>${NOTES[0].text}`;

      noteBox.addEventListener("click", () => showNote(noteIndex + 1));

      // Event bindings
      driftSlider.addEventListener("input", () => {
        drift = parseFloat(driftSlider.value);
        driftVal.textContent = drift.toFixed(3);
        resetTrace(false);
        if (soundOn) tuneSound();
      });

      dampSlider.addEventListener("input", () => {
        damping = parseFloat(dampSlider.value);
        dampVal.textContent = damping.toFixed(4);
        resetTrace(false);
      });

      plate.addEventListener("click", () => resetTrace(true));
      redrawBtn.addEventListener("click", () => resetTrace(true));

      pauseBtn.addEventListener("click", () => {
        if (resting) {
          resetTrace(true);
          return;
        }
        paused = !paused;
        updateStatus();
      });

      soundBtn.addEventListener("click", () => {
        if (soundOn) stopSound();
        else startSound();
      });

      themeBtn.addEventListener("click", () => {
        const isNight = document.documentElement.getAttribute("data-theme") === "night";
        if (isNight) {
          document.documentElement.removeAttribute("data-theme");
          themeBtn.textContent = "night";
          themeBtn.setAttribute("aria-pressed", "false");
        } else {
          document.documentElement.setAttribute("data-theme", "night");
          themeBtn.textContent = "day";
          themeBtn.setAttribute("aria-pressed", "true");
        }
        replayAllPoints();
      });

      saveBtn.addEventListener("click", () => {
        const out = document.createElement("canvas");
        const exportSize = 1400;
        out.width = exportSize;
        out.height = exportSize;
        const ctx = out.getContext("2d");

        ctx.fillStyle = cssVar("--bg-plate");
        ctx.fillRect(0, 0, exportSize, exportSize);

        // Re-render current trace sharply at export resolution
        const half = exportSize * 0.5;
        const scale = exportSize * 0.415;
        ctx.strokeStyle = cssVar("--trace");
        ctx.lineWidth = 1.4;
        ctx.lineCap = "round";
        ctx.lineJoin = "round";

        const CHUNK = 160;
        for (let i = 1; i < points.length; i += CHUNK) {
          const end = Math.min(points.length, i + CHUNK);
          ctx.beginPath();
          ctx.moveTo(half + points[i - 1].x * scale, half + points[i - 1].y * scale);
          for (let j = i; j < end; j++) {
            ctx.lineTo(half + points[j].x * scale, half + points[j].y * scale);
          }
          ctx.stroke();
        }

        // Subtle plate inscription
        const r = RATIOS[ratioIndex];
        ctx.fillStyle = cssVar("--ink-faint");
        ctx.font = "20px ui-monospace, Menlo, Consolas, monospace";
        ctx.fillText(`${r.name} · ${r.label} · drift ${drift.toFixed(3)}`, 42, exportSize - 38);

        const link = document.createElement("a");
        link.download = `between-questions-${r.name.replace(/\s+/g, "-")}.png`;
        link.href = out.toDataURL("image/png");
        link.click();
      });

      window.addEventListener("keydown", (e) => {
        if (e.target.tagName === "INPUT" || e.target.tagName === "BUTTON") return;
        if (e.code === "Space") {
          e.preventDefault();
          if (resting) resetTrace(true);
          else {
            paused = !paused;
            updateStatus();
          }
        } else if (e.key === "r" || e.key === "R") {
          resetTrace(true);
        }
      });

      let resizeTimer = null;
      window.addEventListener("resize", () => {
        clearTimeout(resizeTimer);
        resizeTimer = setTimeout(resizeCanvas, 80);
      });

      // Initialize
      resizeCanvas();
      resetTrace(false);
      requestAnimationFrame(tick);
    })();
  </script>
</body>
</html>
