      body: "At the edge of a pavement, a plant has found enough earth. It has no opinion about the pavement. It is busy making another leaf."
    }
  ];
  let current = 0;
  const buttons = document.querySelectorAll(".dot");
  function show(index) {
    current = index;
    document.getElementById("note-title").textContent = notes[index].title;
    document.getElementById("note-body").textContent = notes[index].body;
    document.getElementById("note-number").textContent =
