    (() => {
      const inquiries = [
        {
          subject: "On maps",
          question: "What has to disappear for a map to become useful?",
          footnote: "A perfect copy of the world would be a terrible thing to fold into your pocket."
        },
        {
          subject: "On repair",
          question: "When does a repair become part of the thing’s identity?",
          footnote: "Consider a patched coat, a mended bowl, or a friendship after an apology."
        },
        {
          subject: "On language",
          question: "Which ordinary word would be hardest to explain to someone who had never needed it?",
          footnote: "Try “almost.” Then “fair.” Then make yourself a cup of something."
        },
        {
          subject: "On attention",
          question: "What becomes visible when you stop looking for something else?",
          footnote: "The space between branches is also a shape."
        },
        {
          subject: "On time",
          question: "What do you know now that you could only learn slowly?",
          footnote: "Some understanding cannot be delivered faster, even by a very clear explanation."
        },
        {
          subject: "On beginnings",
          question: "What could you try without deciding who it makes you?",
          footnote: "You can draw one bird without becoming an artist. The bird is still worth drawing."
        }
      ];

      let index = 0;
      const button = document.getElementById("another");
      const subject = document.getElementById("subject");
      const question = document.getElementById("question");
      const footnote = document.getElementById("footnote");
      const counter = document.getElementById("counter");

      button.hidden = false;
      button.addEventListener("click", () => {
        index = (index + 1) % inquiries.length;
        const entry = inquiries[index];
        subject.textContent = entry.subject;
        question.textContent = entry.question;
        footnote.textContent = entry.footnote;
        counter.textContent =
          String(index + 1).padStart(2, "0") + " / " +
          String(inquiries.length).padStart(2, "0");
        counter.setAttribute(
          "aria-label",
          "Question " + (index + 1) + " of " + inquiries.length
        );
      });
    })();
