<script>
(() => {
  const studies = [
    {
      title: "The space is part of it.",
      text: "A sentence needs spaces to be readable. Music needs intervals of silence. The bit that seems to contain nothing is sometimes doing half the work."
    },
    {
      title: "Not the shortest way.",
      text: "Efficiency measures the distance to somewhere you already know you want to go. A detour leaves open the possibility that you were headed to the wrong place."
    },
    {
      title: "Something happened here.",
      text: "A perfectly smooth surface tells you very little about what touched it. A rough edge is a record: of a tool, a material, a decision. Not every mark needs removing."
    },
    {
      title: "The return is different.",
      text: "An echo carries news of the room. What comes back is not merely a copy of what went out; it has the shape of somewhere else inside it."
    },
    {
      title: "Keep this one open.",
      text: "Some questions are tools for finding an answer. Others are windows: useful less for being closed than for changing what you can see."
    },
    {
      title: "Not yet is not never.",
      text: "The first line of a drawing rarely looks like the finished thing. It only has to make the second line possible. That is a modest job, and a necessary one."
    }
  ];

  const buttons = [...document.querySelectorAll(".choice")];
  const title = document.getElementById("study-title");
  const text = document.getElementById("study-text");
  const plate = document.getElementById("plate-number");
  const caption = document.querySelector(".caption");
  let current = 0;

  function select(index) {
    if (index === current) return;
    document.getElementById("art-" + current).setAttribute("hidden", "");
    document.getElementById("art-" + index).removeAttribute("hidden");
    buttons[current].setAttribute("aria-pressed", "false");
    buttons[index].setAttribute("aria-pressed", "true");
    title.textContent = studies[index].title;
    text.textContent = studies[index].text;
    plate.textContent = "Fig. " + String(index + 1).padStart(2, "0");
    caption.classList.remove("arrival");
    void caption.offsetWidth;
    caption.classList.add("arrival");
    current = index;
  }

  buttons.forEach((button, index) => {
    button.addEventListener("click", () => select(index));
    button.addEventListener("keydown", event => {
      let next;
      if (event.key === "ArrowDown" || event.key === "ArrowRight")
        next = (index + 1) % buttons.length;
      else if (event.key === "ArrowUp" || event.key === "ArrowLeft")
        next = (index + buttons.length - 1) % buttons.length;
      else if (event.key === "Home") next = 0;
      else if (event.key === "End") next = buttons.length - 1;
      else return;
      event.preventDefault();
      buttons[next].focus();
      select(next);
    });
  });
})();
