<script>
(function () {
  const canvas = document.getElementById("field");
  const ctx = canvas.getContext("2d");
  const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const mouse = { x: 0, y: 0, on: false };
  let w = 0, h = 0, dust = [];

  function resize() {
    w = canvas.width = window.innerWidth;
    h = canvas.height = window.innerHeight;
  }

  function seed() {
    const n = Math.min(280, Math.floor((w * h) / 9000));
    dust = [];
    for (let i = 0; i < n; i++) {
      dust.push({
        x: Math.random() * w,
        y: Math.random() * h,
        vx: (Math.random() - 0.5) * 0.18,
        vy: (Math.random() - 0.5) * 0.12,
        r: Math.random() * 1.6 + 0.3,
        a: Math.random() * 0.45 + 0.08
      });
    }
  }

  function step() {
    ctx.clearRect(0, 0, w, h);
    for (let i = 0; i < dust.length; i++) {
      const d = dust[i];
      if (!reduce && mouse.on) {
        const dx = d.x - mouse.x;
        const dy = d.y - mouse.y;
        const dist = Math.sqrt(dx * dx + dy * dy) + 0.001;
        const f = 28 / (dist * dist);
        d.vx += (dx / dist) * Math.min(f, 0.05);
        d.vy += (dy / dist) * Math.min(f, 0.05);
      }
      d.vx *= 0.99;
      d.vy *= 0.99;
      d.x += d.vx + 0.04;
      d.y += d.vy;
      if (d.x > w + 10) d.x = -10;
      if (d.x < -10) d.x = w + 10;
      if (d.y > h + 10) d.y = -10;
      if (d.y < -10) d.y = h + 10;
      ctx.beginPath();
      ctx.fillStyle = "rgba(230, 220, 196," + d.a + ")";
      ctx.arc(d.x, d.y, d.r, 0, Math.PI * 2);
      ctx.fill();
    }
    if (!reduce) requestAnimationFrame(step);
  }

  window.addEventListener("resize", function () { resize(); seed(); });
  window.addEventListener("pointermove", function (e) {
    mouse.x = e.clientX;
    mouse.y = e.clientY;
    mouse.on = true;
  });
  window.addEventListener("pointerleave", function () { mouse.on = false; });
  window.addEventListener("pointerdown", function (e) {
    for (let i = 0; i < 18; i++) {
      const ang = Math.random() * Math.PI * 2;
      const sp = Math.random() * 2.2 + 0.4;
      dust.push({
        x: e.clientX,
        y: e.clientY,
        vx: Math.cos(ang) * sp,
        vy: Math.sin(ang) * sp,
        r: Math.random() * 1.8 + 0.4,
        a: 0.55
      });
    }
    if (dust.length > 420) dust.splice(0, dust.length - 420);
  });

  resize();
  seed();
  if (reduce) step();
  else requestAnimationFrame(step);
})();
</script>
</body>
