      var canvas = document.getElementById("sky");
      var ctx = canvas.getContext("2d");
      var stars = [];
      var reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

      function resize() {
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
