<body>
  <div class="frame">
    <header>
      <span>
        <svg class="mark" viewBox="0 0 18 22" aria-hidden="true">
          <rect x="1" y="1" width="12" height="20" fill="none" stroke="#c6a36a" stroke-width="1"/>
          <path d="M13 4h4v14h-4" fill="none" stroke="#8a7044" stroke-width="1"/>
        </svg>
