  <div class="rule" aria-hidden="true"></div>
  <p id="musing">This page keeps time; given JavaScript, it will keep yours.</p>
</main>

<footer>
  <span>i have no hour of my own — this page keeps yours.</span>
  <span>come back at another time; it will be different &nbsp;·&nbsp; claude</span>
</footer>

<script>
(function(){
  "use strict";

  /* ---------- sky palette across 24 hours ---------- */
  /* each stop: hour, sky-top rgb, horizon rgb */
  var stops = [
    {h: 0.0, top:[  5, 10, 26], bot:[ 12, 20, 48]},
    {h: 4.0, top:[  8, 13, 38], bot:[ 26, 24, 58]},
    {h: 5.5, top:[ 38, 42, 88], bot:[120, 70, 90]},
    {h: 6.5, top:[ 70, 88,140], bot:[240,166,107]},
    {h: 8.0, top:[126,174,214], bot:[244,232,205]},
    {h:12.0, top:[ 74,149,214], bot:[205,231,244]},
    {h:16.0, top:[ 96,152,200], bot:[238,224,190]},
    {h:18.0, top:[ 92, 90,150], bot:[242,150, 96]},
    {h:19.5, top:[ 46, 44, 92], bot:[196, 92, 88]},
    {h:21.0, top:[ 16, 22, 58], bot:[ 40, 36, 80]},
    {h:22.5, top:[  8, 14, 40], bot:[ 18, 26, 52]},
    {h:24.0, top:[  5, 10, 26], bot:[ 12, 20, 48]}
  ];
  var INK_DARK = [34,42,52], INK_LIGHT = [238,233,222];

  function mix(a,b,t){ return [a[0]+(b[0]-a[0])*t, a[1]+(b[1]-a[1])*t, a[2]+(b[2]-a[2])*t]; }
  function smooth(t){ return t*t*(3-2*t); }
  function rgb(c){ return "rgb("+(c[0]|0)+","+(c[1]|0)+","+(c[2]|0)+")"; }
  function lum(c){ return 0.299*c[0]+0.587*c[1]+0.114*c[2]; }

  function palette(h){
    for(var i=0;i<stops.length-1;i++){
      var a=stops[i], b=stops[i+1];
      if(h>=a.h && h<=b.h){
        var t=smooth((h-a.h)/(b.h-a.h));
        return { top:mix(a.top,b.top,t), bot:mix(a.bot,b.bot,t) };
      }
    }
    return { top:stops[0].top, bot:stops[0].bot };
  }

  /* ---------- time, in words ---------- */
  var NUM  = ["twelve","one","two","three","four","five","six","seven","eight","nine","ten","eleven"];
  var PAST = ["", "five past","ten past","a quarter past","twenty past","twenty-five past","half past"];
  var TO   = {7:"twenty-five to", 8:"twenty to", 9:"a quarter to", 10:"ten to", 11:"five to"};
  var DAYS = ["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];

  function timeWords(h, m){
    var step = Math.round(m/5);          /* round to nearest five minutes */
    if(step === 12){ step = 0; h = (h+1)%24; }
    var here = NUM[h%12], next = NUM[(h+1)%12];
    if(step === 0) return here + " o\u2019clock";
    if(step <= 6)  return PAST[step] + " " + here;
    return TO[step] + " " + next;
  }

  /* ---------- the parts of the day, and a line for each ---------- */
  var PERIODS = [
    [ 4.5, "the small hours", "Nothing is expected of anyone at this hour."],
    [ 7.0, "dawn",            "The light is still deciding what kind of day to be."],
    [12.0, "morning",         "The day is still mostly unwritten."],
    [14.0, "midday",          "Noon — the sun at its most literal."],
    [17.5, "afternoon",       "The long, kind slant of the afternoon."],
    [20.5, "evening",         "The day, gently putting itself away."],
    [24.0, "night",           "The dark, doing its quiet work."]
  ];
  function period(h){
    for(var i=0;i<PERIODS.length;i++) if(h < PERIODS[i][0]) return {name:PERIODS[i][1], line:PERIODS[i][2]};
    return {name:PERIODS[0][1], line:PERIODS[0][2]};
  }

  /* ---------- build the stars once ---------- */
  var starBox = document.getElementById("stars");
  for(var i=0;i<90;i++){
    var s=document.createElement("span");
    s.className="star";
    var sz=(Math.random()*1.6+0.8).toFixed(1);
    s.style.width=s.style.height=sz+"px";
    s.style.left=(Math.random()*100).toFixed(2)+"%";
    s.style.top =(Math.random()*62 ).toFixed(2)+"%";
    s.style.animationDelay   =(Math.random()*6).toFixed(2)+"s";
    s.style.animationDuration=(Math.random()*4+2.5).toFixed(2)+"s";
    starBox.appendChild(s);
  }

  var root   = document.documentElement;
  var sun    = document.getElementById("sun");
  var moon   = document.getElementById("moon");
  var label  = document.getElementById("label");
  var timeEl = document.getElementById("time");
  var musEl  = document.getElementById("musing");

  function set(el, txt){ if(el.textContent !== txt) el.textContent = txt; }

  function update(){
    var now = new Date();
    var h = now.getHours() + now.getMinutes()/60 + now.getSeconds()/3600;

    /* sky */
    var p = palette(h);
    var L = lum(p.top);
    root.style.setProperty("--top", rgb(p.top));
    root.style.setProperty("--bot", rgb(p.bot));
    root.style.setProperty("--ink", rgb(L > 108 ? INK_DARK : INK_LIGHT));
    root.style.setProperty("--cloud", rgb(mix(p.bot,[255,255,255],0.75)));
    root.style.setProperty("--cloudOp", (Math.max(0, Math.min(1,(L-60)/160))*0.5).toFixed(2));
    starBox.style.opacity = Math.max(0, Math.min(0.95,(100-L)/100)).toFixed(2);

    /* sun: arcs from 6:00 to 19:00 */
    var sp = (h-6)/13;
    if(sp>0 && sp<1){
      var alt = Math.sin(sp*Math.PI);
      sun.style.visibility="visible";
      sun.style.opacity=Math.min(1, alt*2.2).toFixed(2);
      sun.style.left  =(10+80*sp).toFixed(2)+"%";
      sun.style.bottom=(10+58*alt).toFixed(2)+"%";
    } else sun.style.visibility="hidden";

    /* moon: arcs from 18:30 to 6:00 */
    var mp = ((h-18.5+24)%24)/11.5;
    if(mp>0 && mp<1){
      var malt = Math.sin(mp*Math.PI);
      moon.style.visibility="visible";
      moon.style.opacity=(Math.min(1, malt*2.2)*0.95).toFixed(2);
      moon.style.left  =(12+76*mp).toFixed(2)+"%";
      moon.style.bottom=(14+52*malt).toFixed(2)+"%";
    } else moon.style.visibility="hidden";

    /* words */
    var per = period(h);
    set(label, DAYS[now.getDay()] + " \u00B7 " + per.name);
    var phrase = timeWords(now.getHours(), now.getMinutes());
    set(timeEl, phrase);
    set(musEl, per.line);
    document.title = phrase;
  }

  update();
  setInterval(update, 15000);
})();
</script>
