      m.vy += (Math.random() - .5) * .03;
      if (mouse.active) {
        const dx = m.x - mouse.x, dy = m.y - mouse.y;
        const d = Math.hypot(dx, dy);
        if (d < 130 && d > 0) { m.vx += dx / d * .012; m.vy += dy / d * .012; }
