        b.setAttribute("aria-pressed", active ? "true" : "false");
      });
      if(prefersReduced) draw(0);
    });
  });

  /* ---------- leave a word ---------- */
  var wordForm = document.getElementById("wordForm");
  var wordInput = document.getElementById("wordInput");
  var wordField = document.getElementById("wordField");
  var fieldEmpty = document.getElementById("fieldEmpty");
  var wordColors = ["var(--accent)", "var(--accent2)", "var(--accent3)"];

  wordForm.addEventListener("submit", function(e){
    e.preventDefault();
    var word = wordInput.value.trim();
    if(!word){
      wordInput.classList.remove("shake");
      void wordInput.offsetWidth;
      wordInput.classList.add("shake");
      wordInput.focus();
      return;
    }
    if(fieldEmpty && fieldEmpty.parentNode) fieldEmpty.parentNode.removeChild(fieldEmpty);
    var span = document.createElement("span");
    span.className = "floating-word";
    span.textContent = word;
    span.style.left = (6 + Math.random() * 62) + "%";
    span.style.top = (8 + Math.random() * 74) + "%";
    span.style.fontSize = (1.05 + Math.random() * 0.6) + "rem";
